import (
	"net/url"
	"regexp"
	"strings"
	"path/filepath"
)

func validateVolume(src *v1.GitRepoVolumeSource) error {
	// Validate repository URL
	if src.Repository != "" {
		parsedURL, err := url.ParseRequestURI(src.Repository)
		if err != nil || parsedURL.Scheme == "" {
			return fmt.Errorf("invalid repository URL format: %s", src.Repository)
		}
		// Allow only safe URL schemes
		validSchemes := map[string]bool{"http": true, "https": true, "git": true, "ssh": true, "ftp": true, "ftps": true}
		if !validSchemes[parsedURL.Scheme] {
			return fmt.Errorf("unsupported repository URL scheme: %s", parsedURL.Scheme)
		}
	}

	// Validate revision (commit hash, branch, or tag name)
	if src.Revision != "" {
		// Allow alphanumerics, dashes, underscores, periods, and slashes (for refs/heads/...)
		if !regexp.MustCompile(`^[a-zA-Z0-9_\-./]+$`).MatchString(src.Revision) {
			return fmt.Errorf("revision contains invalid characters: %s", src.Revision)
		}
		// Prevent command injection through revision
		if strings.Contains(src.Revision, `;`) || strings.Contains(src.Revision, `&`) {
			return fmt.Errorf("revision contains forbidden characters: %s", src.Revision)
		}
	}

	// Validate directory path
	if src.Directory != "" {
		// Prevent absolute paths
		if filepath.IsAbs(src.Directory) {
			return fmt.Errorf("directory cannot be an absolute path: %s", src.Directory)
		}
		// Prevent path traversal
		if strings.Contains(src.Directory, "..") {
			return fmt.Errorf("directory contains path traversal sequence: %s", src.Directory)
		}
		// Validate directory name characters
		if !regexp.MustCompile(`^[a-zA-Z0-9_\-./]+$`).MatchString(src.Directory) {
			return fmt.Errorf("directory contains invalid characters: %s", src.Directory)
		}
	}

	return nil
}

