func Unpack(r io.Reader, dst string) error {
	// Get absolute path of destination directory for proper path checking
	absDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("Failed to get absolute path for destination: %v", err)
	}

	// Decompress as we read.
	uncompressed, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("Failed to uncompress slug: %v", err)
	}
	defer uncompressed.Close()

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Unpackage all the contents into the directory.
	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

		// Get rid of absolute paths and clean the path
		path := header.Name
		// Remove leading slash to prevent absolute path
		if len(path) > 0 && path[0] == '/' {
			path = path[1:]
		}
		// Join with destination and clean
		path = filepath.Join(dst, path)
		path = filepath.Clean(path)

		// Get absolute path of the final path
		absPath, err := filepath.Abs(path)
		if err != nil {
			return fmt.Errorf("Failed to get absolute path for file: %v", err)
		}

		// Verify the cleaned path is within the destination directory
		if !strings.HasPrefix(absPath, absDst) {
			return fmt.Errorf("Path traversal detected: %q", header.Name)
		}

		// Make the directories to the path
		dir := filepath.Dir(absPath)
		if err := safeMkdirAll(absDst, dir, 0755); err != nil {
			return fmt.Errorf("Failed to create directory %q: %v", dir, err)
		}

		// Handle symlinks.
		if header.Typeflag == tar.TypeSymlink {
			// Disallow absolute targets.
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target",
					header.Name, header.Linkname)
			}

			// Clean the link name
			cleanedLink := filepath.Clean(header.Linkname)

			// Ensure the link target is within the destination directory
			target := filepath.Join(dir, cleanedLink)
			absTarget, err := filepath.Abs(target)
			if err != nil {
				return fmt.Errorf("Failed to get absolute path for symlink target: %v", err)
			}

			// Resolve all symlinks in the target path
			resolvedTarget, err := filepath.EvalSymlinks(absTarget)
			if err != nil && !os.IsNotExist(err) {
				return fmt.Errorf("Failed to resolve symlink target: %v", err)
			}

			// Check if target would escape destination
			if resolvedTarget != "" && !strings.HasPrefix(resolvedTarget, absDst) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has external target",
					header.Name, header.Linkname)
			}

			// Create the symlink.
			if err := os.Symlink(header.Linkname, absPath); err != nil {
				return fmt.Errorf("Failed creating symlink (%q -> %q): %v",
					header.Name, header.Linkname, err)
			}

			continue
		}

		// Only unpack regular files from this point on.
		if header.Typeflag == tar.TypeDir {
			continue
		} else if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
			return fmt.Errorf("Failed creating %q: unsupported type %c", absPath,
				header.Typeflag)
		}

		// Check if this path would escape through existing symlinks
		resolvedPath, err := filepath.EvalSymlinks(absPath)
		if err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("Failed to resolve path: %v", err)
		}

		// If the path exists and resolves to outside destination, reject it
		if resolvedPath != "" && !strings.HasPrefix(resolvedPath, absDst) {
			return fmt.Errorf("Path traversal through symlink detected: %q", header.Name)
		}

		// Open a handle to the destination.
		fh, err := os.Create(absPath)
		if err != nil {
			// This mimics tar's behavior wrt the tar file containing duplicate files
			// and it allowing later ones to clobber earlier ones even if the file
			// has perms that don't allow overwriting.
			if os.IsPermission(err) {
				os.Chmod(absPath, 0600)
				fh, err = os.Create(absPath)
			}

			if err != nil {
				return fmt.Errorf("Failed creating file %q: %v", absPath, err)
			}
		}

		// Copy the contents.
		_, err = io.Copy(fh, untar)
		fh.Close()
		if err != nil {
			return fmt.Errorf("Failed to copy slug file %q: %v", absPath, err)
		}

		// Restore the file mode. We have to do this after writing the file,
		// since it is possible we have a read-only mode.
		mode := header.FileInfo().Mode()
		if err := os.Chmod(absPath, mode); err != nil {
			return fmt.Errorf("Failed setting permissions on %q: %v", absPath, err)
		}
	}
	return nil
}

// safeMkdirAll creates directories while validating symlink targets
func safeMkdirAll(baseDir, dir string, perm os.FileMode) error {
	// Check if the directory is already within the base directory
	if !strings.HasPrefix(dir, baseDir) {
		return fmt.Errorf("Directory %q escapes base directory %q", dir, baseDir)
	}

	// Get relative path from base directory
	relDir, err := filepath.Rel(baseDir, dir)
	if err != nil {
		return fmt.Errorf("Failed to compute relative directory: %v", err)
	}

	// Check if relative path starts with ".." which would indicate escaping
	if strings.HasPrefix(relDir, "..") {
		return fmt.Errorf("Directory %q escapes base directory", dir)
	}

	// Check each component of the path
	currentPath := baseDir
	components := strings.Split(relDir, string(filepath.Separator))

	for _, comp := range components {
		if comp == "" || comp == "." {
			continue
		}

		currentPath = filepath.Join(currentPath, comp)

		// Check if the current path exists
		fi, err := os.Lstat(currentPath)
		if err == nil {
			// Path exists - check if it's a symlink
			if fi.Mode()&os.ModeSymlink != 0 {
				// Resolve the symlink target
				resolvedPath, err := filepath.EvalSymlinks(currentPath)
				if err != nil {
					return fmt.Errorf("failed to resolve symlink %q: %v", currentPath, err)
				}
				// Get absolute path of resolved target
				absResolved, err := filepath.Abs(resolvedPath)
				if err != nil {
					return fmt.Errorf("failed to get absolute path for resolved symlink %q: %v", resolvedPath, err)
				}
				// Verify resolved path is within base directory
				if !strings.HasPrefix(absResolved, baseDir) {
					return fmt.Errorf("symlink %q points outside destination directory", currentPath)
				}
				// Update currentPath to resolved path for subsequent components
				currentPath = absResolved
			} else if !fi.IsDir() {
				// Exists but is not a directory
				return fmt.Errorf("path component %q exists but is not a directory", currentPath)
			}
		} else if os.IsNotExist(err) {
			// Create directory if it doesn't exist
			if err := os.Mkdir(currentPath, perm); err != nil {
				return fmt.Errorf("failed to create directory: %v", err)
			}
		} else {
			// Other error (permission denied, etc.)
			return fmt.Errorf("failed to stat path: %v", err)
		}
	}
	return nil
}

