def deny_uploads_containing_script_tag(uploaded_file):
    buffer = b''
    forbidden_patterns = [b"<script", b"onload=", b"onclick=", b"onerror=", b"onmouseover=", b"onfocus="]
    max_pattern_length = max(len(p) for p in forbidden_patterns) if forbidden_patterns else 0
    for chunk in uploaded_file.chunks(2048):
        # Combine previous buffer with current chunk and convert to lowercase
        combined = buffer + chunk.lower()
        # Check for any forbidden pattern
        for pattern in forbidden_patterns:
            if pattern in combined:
                raise ValidationError(_("File contains forbidden content"))
        # Keep last (max_pattern_length - 1) bytes to handle split across chunks
        if max_pattern_length > 1:
            buffer = combined[-(max_pattern_length - 1):] if len(combined) >= max_pattern_length - 1 else combined
        else:
            buffer = b''

