def prepare(
    self,
    *, 
    conn: SnowflakeConnection,
    authenticator: str,
    service_name: str | None,
    account: str,
    user: str,
    **kwargs: Any,
) -> None:
    """Web Browser based Authentication."""
    logger.debug("authenticating by Web Browser")

    socket_connection = self._socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        try:
            socket_connection.bind(
                (
                    os.getenv("SF_AUTH_SOCKET_ADDR", "localhost"),
                    int(os.getenv("SF_AUTH_SOCKET_PORT", 0)),
                )
            )
        except socket.gaierror as ex:
            if ex.args[0] == socket.EAI_NONAME:
                raise OperationalError(
                    msg="localhost is not found. Ensure /etc/hosts has "
                    "localhost entry.",
                    errno=ER_NO_HOSTNAME_FOUND,
                )
            else:
                raise ex
        socket_connection.listen(0)  # no backlog
        callback_port = socket_connection.getsockname()[1]

        print(
            "Initiating login request with your identity provider. A "
            "browser window should have opened for you to complete the "
            "login. If you can't see it, check existing browser windows, "
            "or your OS settings. Press CTRL+C to abort and try again..."
        )

        logger.debug("step 1: query GS to obtain SSO url")
        sso_url = self._get_sso_url(
            conn, authenticator, service_name, account, callback_port, user
        )

        # Validate the SSO URL before opening it
        if not self._validate_redirect_url(sso_url):
            self._handle_failure(
                conn=conn,
                ret={
                    "code": ER_INVALID_REDIRECT_URL,
                    "message": "Invalid SSO URL format. Please check your authentication settings."
                },
            )
            return

        logger.debug("step 2: open a browser")
        print(f"Going to open: {sso_url} to authenticate...")
        if not self._webbrowser.open_new(sso_url):
            print(
                "We were unable to open a browser window for you, "
                "please open the url above manually then paste the "
                "URL you are redirected to into the terminal."
            )
            url = self._get_user_input("Enter the URL the SSO URL redirected you to: ")

            # Validate URL format and sanitize input
            if not self._validate_redirect_url(url):
                self._handle_failure(
                    conn=conn,
                    ret={
                        "code": ER_INVALID_REDIRECT_URL,
                        "message": "Invalid redirect URL format. Please check and try again."
                    },
                )
                return

            self._process_get_url(url)
            if not self._token:
                # Input contained no token, either URL was incorrectly pasted,
                # empty or just wrong
                self._handle_failure(
                    conn=conn,
                    ret={
                        "code": ER_UNABLE_TO_OPEN_BROWSER,
                        "message": (
                            "Unable to open a browser in this environment and "
                            "SSO URL contained no token"
                        ),
                    },
                )
                return
        else:
            logger.debug("step 3: accept SAML token")
            self._receive_saml_token(conn, socket_connection)
    finally:
        socket_connection.close()

def _get_user_input(self, prompt: str) -> str:
    """Wrapper for input() to allow mocking in tests."""
    return input(prompt)

def _validate_redirect_url(self, url: str) -> bool:
    """Validate the redirect URL to prevent command injection."""
    # Check for basic URL format
    if not url.startswith(('http://', 'https://')):
        logger.warning(f"URL does not use HTTP/HTTPS: {url}")
        return False

    # Parse the URL
    try:
        from urllib.parse import unquote_plus, urlparse, parse_qs
        # Decode URL components to detect encoded malicious characters
        # Decode multiple times to handle nested encoding
        decoded_url = url
        for _ in range(3):  # Decode up to 3 times to handle nested encoding
            decoded_url = unquote_plus(decoded_url)
            if decoded_url == url:
                break  # No more decoding possible
            url = decoded_url

        parsed_url = urlparse(decoded_url)

        # Check for suspicious characters in any part of the URL
        suspicious_chars = [';', '&', '|', '$', '`', '(', ')', '{', '}', '[', ']', '\\', '!', "'", '"', '<', '>', '*', '?', ':', '@', '=', '+', ',', '/', '#']
        for part in [parsed_url.scheme, parsed_url.netloc, parsed_url.path, parsed_url.query, parsed_url.params, parsed_url.fragment]:
            if any(char in part for char in suspicious_chars):
                logger.warning(f"Potential command injection attempt in URL: {url}")
                return False

        # Check if the URL contains expected authentication parameters
        query_params = parse_qs(parsed_url.query)
        if not any(param in query_params for param in ['token', 'saml', 'session', 'code']):
            logger.warning(f"Missing authentication parameters in URL: {url}")
            return False

        # Verify domain is trusted
        trusted_domains = ['snowflake.com', 'snowflakecomputing.com']
        if parsed_url.netloc:
            domain_parts = parsed_url.netloc.split('.')
            if len(domain_parts) >= 2:
                domain = '.'.join(domain_parts[-2:])
                if domain not in trusted_domains and not any(tld in domain for tld in trusted_domains):
                    logger.warning(f"Untrusted domain in redirect URL: {domain}")
                    return False

        return True
    except Exception as e:
        logger.error(f"Error validating redirect URL: {str(e)}")
        return False

