patch:
exports.killByPort = function (port) {
  var processId = null;
  // Validate port input to allow only digits
  const portStr = port.toString();
  if (!/^\d+$/.test(portStr)) {
    return;
  }

  try {
    // Use execFileSync with arguments array to prevent shell injection
    processId = require('child_process').execFileSync('lsof', ['-t', `-i:${portStr}`], { encoding: 'utf8' }).trim();
  } catch (e) {
    // Ignore errors including 'no process found' (exit code 1)
    if (e.status !== 1) throw e;
  }

  if (processId) {
    try {
      require('child_process').execFileSync('kill', [processId]);
    } catch (e) {}
  }
};

