const { execFileSync } = require('child_process');

exports.killByPort = function (port) {
  var processId = null;

  // Validate port input to allow only digits and valid port range
  const portStr = port.toString();
  if (!/^\d+$/.test(portStr)) {
    return;
  }

  const portNum = parseInt(portStr, 10);
  if (portNum < 1 || portNum > 65535) {
    return;
  }

  try {
    // Use execFileSync with arguments array to prevent shell injection
    processId = execFileSync('lsof', ['-t', '-i', `:${portNum}`], { encoding: 'utf8' }).trim();
  } catch (e) {
    // Ignore errors including 'no process found' (exit code 1)
    if (e.status !== 1) throw e;
  }

  if (processId) {
    // Split output in case there are multiple PIDs and validate each PID
    const pids = processId.split('\n').filter(pid => {
      // Ensure PID is a valid positive integer
      return pid.trim() !== '' && /^\d+$/.test(pid.trim());
    });

    try {
      // Kill each process individually with validated PID
      pids.forEach(pid => {
        execFileSync('kill', [pid.trim()]);
      });
    } catch (e) {
      // Handle kill errors if needed
    }
  }
};

