const { execFile } = require('child_process');

function splitCommand(command) {
    const args = [];
    let current = '';
    let inQuotes = false;
    let quoteChar = '';
    let escaped = false;

    for (let i = 0; i < command.length; i++) {
        const c = command[i];
        if (escaped) {
            current += c;
            escaped = false;
            continue;
        }
        if (c === '\\') {
            escaped = true;
            continue;
        }
        if (inQuotes) {
            if (c === quoteChar) {
                inQuotes = false;
            } else {
                current += c;
            }
        } else {
            if (c === '\'' || c === '"') {
                inQuotes = true;
                quoteChar = c;
            } else if (c === ' ') {
                if (current) {
                    args.push(current);
                    current = '';
                }
            } else {
                current += c;
            }
        }
    }
    if (current) {
        args.push(current);
    }
    return args;
}

const parts = splitCommand(command);
const executable = parts[0];
const args = parts.slice(1);

execFile(executable, args, function(err, stdout, stderr) {
    if (err) {
        callback(err)
        return
    }

    if (stderr) {
        callback(new Error(err))
        return
    }

    var entries = parse(stdout, options)

    callback(null, entries)
})

