function template(literal, data) {
  // Use regex to find all ${...} patterns and replace with data values
  return literal.replace(/\$\{([^}]+)\}/gm, (match, propPath) => {
    // Split property path into individual properties
    const props = propPath.trim().split('.');
    let value = data;

    // Traverse the data object to find the property value
    for (const prop of props) {
      if (value && typeof value === 'object' && prop in value) {
        value = value[prop];
      } else {
        // Return empty string if property not found
        return '';
      }
    }

    // Convert the value to string before returning
    return String(value);
  });
}

