    const { execFile } = require('child_process');
    const path = require('path');
    return new Promise(function(resolve, reject) {
      // Validate input types
      if (typeof input !== 'string' || typeof start !== 'string' || typeof duration !== 'string' || typeof output !== 'string') {
        reject(new Error("Invalid input types"));
        return;
      }

      // Sanitize file paths to prevent path traversal and command injection
      const sanitizePath = (filePath) => {
        // Remove any directory components and special characters
        const baseName = path.basename(filePath);
        // Allow only alphanumeric, underscores, hyphens, and periods
        return baseName.replace(/[^a-zA-Z0-9_\-\.]/g, '');
      };

      // Validate time format (numbers or time format like HH:MM:SS)
      const isValidTime = (time) => {
        return /^(\d+(\.\d+)?|(\d+:)?\d+:?\d+(\.\d+)?)$/.test(time);
      };

      // Validate and sanitize inputs
      if (!isValidTime(start)) {
        reject(new Error("Invalid start time format"));
        return;
      }

      if (!isValidTime(duration)) {
        reject(new Error("Invalid duration format"));
        return;
      }

      const sanitizedInput = sanitizePath(input);
      const sanitizedOutput = sanitizePath(output);
      const outputPath = `${sanitizedOutput}.mp4`;

      // Resolve full path to prevent path traversal
      const resolvedInput = path.resolve(sanitizedInput);

      if (fs.existsSync(resolvedInput)) {
        execFile(
          'ffmpeg',
