        // Check file permissions
        await fs_access(resolvedPath, fs.constants.R_OK | fs.constants.X_OK);

        // Use execFile with separate arguments to prevent command injection
        const {stdout} = await cp_execFile(resolvedPath, ['--version']);
        if (stdout.toString().match(/ClamAV/) === null) {
            if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary.`);
            return false;
        }
        return true;
    } catch (err) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary: ${err.message}`);
        return false;
    }
}

