def _extract_packages_archive(work_dir):
    package_file = os.path.join(work_dir, "packages.tar")
    if not os.path.exists(package_file):
        return

    # Compute absolute path of work directory with trailing separator
    work_dir_abs = os.path.abspath(work_dir)
    if not work_dir_abs.endswith(os.sep):
        work_dir_abs += os.sep

    tar = tarfile.open(package_file)
    for tarinfo in tar:
        # Calculate normalized destination path
        dest_path = os.path.join(work_dir_abs, tarinfo.name)
        dest_abs = os.path.abspath(dest_path)
        # Validate path is within work directory
        if dest_abs.startswith(work_dir_abs):
            tar.extract(tarinfo, path=work_dir_abs)
    tar.close()
    if '' not in sys.path:
        sys.path.insert(0, '')

