func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path
	prefix := path.Clean(c.Request.Header.Get("X-Forwarded-Prefix"))
	// Validate prefix to prevent path traversal and absolute paths
	if strings.Contains(prefix, "..") || strings.HasPrefix(prefix, "/") {
		prefix = "."
	}
	if prefix != "." {
		prefix = url.QueryEscape(prefix)
		prefix = strings.ReplaceAll(prefix, "%2F", "/")

		p = prefix + "/" + req.URL.Path
	}
	req.URL.Path = p + "/"
	if length := len(p); length > 1 && p[length-1] == '/' {
		req.URL.Path = p[:length-1]
	}
	redirectRequest(c)
}

