	req := c.Request
	p := req.URL.Path
	prefixHeader := req.Header.Get("X-Forwarded-Prefix")
	prefix := ""

	if prefixHeader != "" {
		cleanedPrefix := path.Clean(prefixHeader)
		// Prefix must be an absolute path and not contain ".." segments
		if path.IsAbs(cleanedPrefix) {
			segments := strings.Split(cleanedPrefix, "/")
			valid := true
			for _, seg := range segments {
