    limit: filters.$limit,
    offset: filters.$skip,
    raw: this.raw,
    distinct: true
  }, params.sequelize);

  if (filters.$select) {
    // Validate and filter selected attributes
    q.attributes = filters.$select.filter(col => allowedColumns.includes(col));
  }

  // Validate all columns in query
  this._validateQueryColumns(q, allowedColumns);

