const parseUrl = (url, normalize = false) => {

    // Constants
    const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/;

    const isForbiddenHost = (host) => {
        // Check for loopback addresses and localhost
        if (host === 'localhost' || host === '127.0.0.1' || host === '::1') {
            return true;
        }
        // Check for private IPv4 ranges
        const privateIpv4Regexes = [
            /^10\.\d{1,3}\.\d{1,3}\.\d{1,3}$/,
            /^172\.(1[6-9]|2\d|3[0-1])\.\d{1,3}\.\d{1,3}$/,
            /^192\.168\.\d{1,3}\.\d{1,3}$/
        ];
        for (const regex of privateIpv4Regexes) {
            if (regex.test(host)) {
                return true;
            }
        }
        return false;
    };

    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.");
        err.subject_url = url;
        throw err;
    }

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            };
        }
        url = normalizeUrl(url, normalize);
    }

    const parsed = parsePath(url);

    // Potential git-ssh urls
    if (parsed.protocol === "file") {
        const matched = parsed.href.match(GIT_RE);
        if (matched) {
            const resource = matched[4];
            if (!isForbiddenHost(resource)) {
                parsed.protocols = ["ssh"];
                parsed.protocol = "ssh";
                parsed.resource = resource;
                parsed.host = resource;
                parsed.user = "git";
                parsed.pathname = `/${matched[6]}`;
            }
        }
    }

    return parsed;
};

