getInfo: function () {
  var self = this;
  var args = this.constructGetInfoCommand();
  var promise = new Promise(function (resolve, reject) {
    const spawn = require('child_process').spawn;
    const child = spawn(args[0], args.slice(1));
    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => {
      stdout += data;
    });

    child.stderr.on('data', (data) => {
      stderr += data;
    });

    child.on('error', (err) => {
      reject({
        message: "Failed to get PDF'S information",
        error: err,
        stdout: stdout,
        stderr: stderr
      });
    });

    child.on('close', (code) => {
      if (code !== 0) {
        reject({
          message: "Failed to get PDF'S information",
          error: new Error(`Process exited with code ${code}`),
          stdout: stdout,
          stderr: stderr
        });
      } else {
        resolve(self.parseGetInfoCommandOutput(stdout));
      }
    });
  });
  return promise;
},

