file.copy = function copy(srcpath, destpath, options) {
  // Check for path traversal patterns in input
  const traversalRegex = /\.\.(\\|\/|$)/i;
  if (traversalRegex.test(srcpath) || traversalRegex.test(destpath)) {
    throw new Error('Invalid path: Path traversal detected');
  }

  // Resolve paths to absolute paths
  const absSrcPath = path.resolve(srcpath);
  const absDestPath = path.resolve(destpath);

  if (file.isDir(absSrcPath)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(absDestPath);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(absSrcPath).forEach(function(filepath) {
      copy(path.join(absSrcPath, filepath), path.join(absDestPath, filepath), options);
    });
  } else {
    // Copy a single file.
    file._copy(absSrcPath, absDestPath, options);
  }
};

