file.copy = function copy(srcpath, destpath, options) {
  // Define the base directory (current working directory)
  const baseDir = process.cwd();

  // Resolve paths relative to base directory
  const safeSrc = path.resolve(baseDir, srcpath);
  const safeDest = path.resolve(baseDir, destpath);

  // Verify paths stay within base directory
  if (!safeSrc.startsWith(baseDir) || !safeDest.startsWith(baseDir)) {
    throw new Error('Invalid path: Path traversal detected');
  }

  // Proceed with original functionality
  if (file.isDir(safeSrc)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(safeDest);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(safeSrc).forEach(function(filepath) {
      copy(path.join(safeSrc, filepath), path.join(safeDest, filepath), options);
    });
  } else {
    // Copy a single file.
    file._copy(safeSrc, safeDest, options);
  }
};

