res.location = function location(url) {
  var loc = url;
  var urlModule = require('url');

  // "back" is an alias for the referrer
  if (url === 'back') {
    loc = this.req.get('Referrer') || '/';
  }

  // Validate redirect URL to prevent open redirect
  try {
    var parsedUrl = urlModule.parse(loc);
    if (parsedUrl.host) {
      // Get allowed hosts from application configuration
      var allowedHosts = this.app.get('allowedRedirectHosts') || [];
      if (!allowedHosts.includes(parsedUrl.hostname)) {
        throw new Error('Untrusted redirect host: ' + parsedUrl.hostname);
      }
    }
  } catch (err) {
    console.error('Invalid redirect URL:', err.message);
    loc = '/'; // Default to safe location
  }

  this.setHeader('Location', encodeurl(loc));
  return this;
}

