module.exports = path => {
  let r = '';
  // Strip Windows drive letters to prevent cross-drive access
  if (process.platform === 'win32') {
    // Remove leading drive letter with optional slash or backslash
    path = path.replace(/^[A-Za-z]:[\\/]/, '').replace(/^[A-Za-z]:/, '');
  }
  while (path && isAbsolute(path)) {
    const root = path.charAt(0) === '/' ? '/' : parse(path).root;
    path = path.substr(root.length);
    r += root;
  }
  // Resolve remaining path components to handle .. sequences
  const parts = path.split(/[\\/]/).filter(p => p !== '');
  const resolvedParts = [];
  for (const part of parts) {
    if (part === '..') {
      if (resolvedParts.length > 0) {
        resolvedParts.pop();
      }
      // Ignore if at root to prevent path traversal
    } else {
      resolvedParts.push(part);
    }
  }
  path = resolvedParts.join('/');
  return [r, path];
}

