module.exports = path => {
  let r = '';
  // Strip Windows drive letters to prevent cross-drive access
  if (process.platform === 'win32') {
    // Remove leading drive letter with optional slash or backslash
    path = path.replace(/^[A-Za-z]:[\\/]/, '').replace(/^[A-Za-z]:/, '');
  }
  while (isAbsolute(path)) {
    const root = path.charAt(0) === '/' ? '/' : parse(path).root;
    path = path.substr(root.length);
    r += root;
  }
  // Resolve '..' sequences while preserving original separators
  const segments = [];
  const separators = [];
  const tokens = path.split(/([\\/]+)/);

  for (let i = 0; i < tokens.length; i++) {
    if (i % 2 === 0) { // segment
      const segment = tokens[i];
      if (segment === '..') {
        if (segments.length > 0) {
          segments.pop();
          separators.pop();
        }
      } else if (segment !== '') { // ignore empty segments
        segments.push(segment);
      }
    } else { // separator
      if (segments.length > 0 || (i + 1 < tokens.length && tokens[i+1] !== '')) {
        separators.push(tokens[i]);
      }
    }
  }

  let resolvedPath = '';
  for (let i = 0; i < segments.length; i++) {
    resolvedPath += segments[i];
    if (i < separators.length) {
      resolvedPath += separators[i];
    }
  }
  path = resolvedPath;

  return [r, path];
}

