func (r *Registrator) Certificate(ctx context.Context, in *securityapi.CertificateRequest) (resp *securityapi.CertificateResponse, err error) {
	osRoot, err := safe.StateGet[*secrets.OSRoot](ctx, r.Resources, resource.NewMetadata(secrets.NamespaceName, secrets.OSRootType, secrets.OSRootID, resource.VersionUndefined))
	if err != nil {
		return nil, err
	}

	// Extract client IP from context
	peerInfo, ok := peer.FromContext(ctx)
	if !ok {
		return nil, errors.New("failed to retrieve peer information from context")
	}
	clientAddr := peerInfo.Addr.String()
	clientIP, _, err := net.SplitHostPort(clientAddr)
	if err != nil {
		// If address doesn't have port, use as IP directly
		clientIP = clientAddr
	}

	// Parse CSR to get IP SANs
	csrPEM := []byte(in.Csr)
	block, _ := pem.Decode(csrPEM)
	if block == nil || block.Type != "CERTIFICATE REQUEST" {
		return nil, errors.New("invalid CSR PEM format")
	}
	csr, err := x509.ParseCertificateRequest(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse CSR: %w", err)
	}

	// Validate client IP matches one of the CSR's IP SANs
	clientIPAddr := net.ParseIP(clientIP)
	if clientIPAddr == nil {
		return nil, fmt.Errorf("invalid client IP address: %s", clientIP)
	}

	found := false
	for _, sanIP := range csr.IPAddresses {
		if sanIP.Equal(clientIPAddr) {
			found = true
			break
		}
	}
	if !found {
		return nil, fmt.Errorf("client IP %s is not authorized in CSR SANs", clientIP)
	}

	signed, err := x509.NewCertificateFromCSRBytes(osRoot.TypedSpec().CA.Crt, osRoot.TypedSpec().CA.Key, in.Csr)
	if err != nil {
		return nil, err
	}

	resp = &securityapi.CertificateResponse{
		Ca:  osRoot.TypedSpec().CA.Crt,
		Crt: signed.X509CertificatePEM,
	}

	return resp, nil
}

