	}

	// Extract client IP from context
	peerInfo, ok := peer.FromContext(ctx)
	if !ok {
		return nil, fmt.Errorf("failed to retrieve peer information from context")
	}
	clientAddr := peerInfo.Addr.String()
	clientIP, _, err := net.SplitHostPort(clientAddr)
	if err != nil {
