func (a *AuthenticatorOAuth2Introspection) tokenFromCache(config *AuthenticatorOAuth2IntrospectionConfiguration, token string) (*AuthenticatorOAuth2IntrospectionResult, bool) {
	if !config.Cache.Enabled {
		return nil, false
	}

	// Generate cache key combining token and sorted scopes to ensure scope-specific caching
	sortedScopes := make([]string, len(config.Scopes))
	copy(sortedScopes, config.Scopes)
	sort.Strings(sortedScopes)
	cacheKey := fmt.Sprintf("%s:%s", token, strings.Join(sortedScopes, ","))

	item, found := a.tokenCache.Get(cacheKey)
	if !found {
		return nil, false
	}

	i := item.(*AuthenticatorOAuth2IntrospectionResult)
	expires := time.Unix(i.Expires, 0)
	if expires.Before(time.Now()) {
		a.tokenCache.Del(cacheKey)
		return nil, false
	}

	return i, true
}

