	if err != nil {
		return fmt.Errorf("failed to execute request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("unexpected status code %d when fetching groups", resp.StatusCode)
	}

	var groups []struct {
		Path string `json:"path"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&groups); err != nil {
		return fmt.Errorf("failed to decode groups response: %w", err)
	}

	// Add each group to the session with "group:" prefix
	for _, group := range groups {
		s.Groups = append(s.Groups, fmt.Sprintf("group:%s", group.Path))
	}

	return nil
}

