					}
				}

				// Set UID and GID
				s.Process.User.UID, s.Process.User.GID = uid, gid

				// Get supplemental groups if we have a username
				if usernameResolved != "" {
					gids, err := getSupplementalGroupsFromPath(root, func(gid int, members []string) bool {
