func WithUIDGID(uid, gid uint32) SpecOpts {
	return func(ctx context.Context, client Client, c *containers.Container, s *Spec) error {
		setProcess(s)
		// For LCOW or on Darwin additional GID's not supported
		if s.Windows != nil || runtime.GOOS == "darwin" {
			s.Process.User.UID = uid
			s.Process.User.GID = gid
			return nil
		}

		var root string
		var err error
		if c.Snapshotter == "" && c.SnapshotKey == "" {
			if !isRootfsAbs(s.Root.Path) {
				return errors.New("rootfs absolute path is required")
			}
			root = s.Root.Path
		} else {
			if c.Snapshotter == "" {
				return errors.New("no snapshotter set for container")
			}
			if c.SnapshotKey == "" {
				return errors.New("rootfs snapshot not created for container")
			}
			snapshotter := client.SnapshotService(c.Snapshotter)
			mounts, err := snapshotter.Mounts(ctx, c.SnapshotKey)
			if err != nil {
				return err
			}

			mounts = tryReadonlyMounts(mounts)
			// Use temp mount to access the root filesystem
			err = mount.WithTempMount(ctx, mounts, func(mountRoot string) error {
				root = mountRoot
				return nil
			})
			if err != nil {
				return err
			}
		}

		// Look up user by UID to get supplementary groups
		user, err := UserFromPath(root, func(u user.User) bool {
			return u.Uid == int(uid)
		})
		if err != nil {
			if os.IsNotExist(err) || err == ErrNoUsersFound {
				// User not found in passwd, set UID/GID without additional groups
				s.Process.User.UID = uid
				s.Process.User.GID = gid
				return nil
			}
			return err
		}

		// Get supplemental groups for the user
		gids, err := getSupplementalGroupsFromPath(root, func(g user.Group) bool {
			// Skip primary group
			if g.Gid == int(gid) {
				return false
			}
			for _, entry := range g.List {
				if entry == user.Name {
					return true
				}
			}
			return false
		})
		if err != nil {
			if os.IsNotExist(err) {
				// No groups found, proceed without additional GIDs
			} else {
				return err
			}
		}

		s.Process.User.UID = uid
		s.Process.User.GID = gid
		s.Process.User.AdditionalGids = gids
		return nil
	}
}

