func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {

	typesys := typesystem.New(rc.model)

	tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk)

	if tk != nil {
		err := validation.ValidateTuple(typesys, tk)
		if err == nil && ok {
			return tk, nil
		}
	}

	tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	if err != nil {
		return nil, err
	}

	tk = tuple.GetKey()
	if err := validation.ValidateTuple(typesys, tk); err != nil {
		return nil, nil
	}

	return tk, nil
}

patch:
func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
	tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk)
	if ok {
		// Verify contextual tuple with backend to ensure authorization
		verifiedTuple, err := backend.ReadUserTuple(ctx, rc.store, tk)
		if err == nil && verifiedTuple != nil {
			return tk, nil
		}
	}

	// Read from backend as fallback
	tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	if err != nil {
		return nil, err
	}
	return tuple.GetKey(), nil
}

