func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
	// Always read from backend to ensure authorization checks
	 tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	 if err != nil {
		 return nil, err
	 }

	 // Enforce type restrictions that were previously ignored
	 if tuple != nil && rc.authorizationModel != nil {
		 relation, err := rc.authorizationModel.GetRelation(tuple.Object, tuple.Relation)
		 if err != nil || relation == nil {
			 return nil, errors.New("relation not found in authorization model")
		 }

		 // Check if user type is allowed for this relation
		 userType := strings.Split(tuple.User, ":")[0]
		 allowed := false
		 for _, allowedType := range relation.AllowedUserTypes {
			 if userType == allowedType {
				 allowed = true
				 break
			 }
		 }
		 if !allowed {
			 return nil, errors.New("user type violates relation restrictions")
		 }
	 }

	 return tuple.GetKey(), nil
}

