def detectNFTables():
    import subprocess
    import shutil
    import os

    # Check if safe_exec is available
    try:
        from opencanary.common import safe_exec
        has_safe_exec = True
    except ImportError:
        has_safe_exec = False
        print("[!] WARNING: safe_exec not available, using standard subprocess")

    # Securely locate iptables binary
    iptables_path = shutil.which('iptables')

    # Validate path exists and is in a secure system directory
    if not iptables_path:
        return False

    secure_paths = ['/sbin/', '/usr/sbin/', '/usr/local/sbin/']
    if not any(iptables_path.startswith(path) for path in secure_paths):
        return False

    # Verify file permissions and ownership
    try:
        stat_info = os.stat(iptables_path)
        # Check if file is owned by root
        if stat_info.st_uid != 0:
            return False
        # Check if file has secure permissions (not writable by others)
        if stat_info.st_mode & 0o002:
            return False
    except OSError:
        return False

    try:
        if has_safe_exec:
            # Use safe_exec if available
            exit_code, output = safe_exec(iptables_path, ["--version"])
            return exit_code == 0 and b"nf_tables" in output
        else:
            # Fallback to subprocess with absolute path
            return b"nf_tables" in subprocess.check_output([iptables_path, "--version"], stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError:
        return False
    except Exception:
        return False

