var BAD_PROTOCOLS    = [ 'vbscript', 'javascript', 'file' ];

function validateLink(url) {
  // url should be normalized at this point, and existing entities are decoded
  //
  var str = url.trim().toLowerCase();
  var colonIndex = str.indexOf(':');

  if (colonIndex === -1) {
    return true; // No protocol, considered safe
  }

  var protocol = str.substring(0, colonIndex);

  // Check for bad protocols
  if (BAD_PROTOCOLS.indexOf(protocol) !== -1) {
    return false;
  }

  // Handle data protocol specially
  if (protocol === 'data') {
    // Split data URL into parts
    var dataParts = str.substring(colonIndex + 1).split(';');
    var mediaType = dataParts[0];

    // Allow only image data URLs
    if (mediaType.startsWith('image/')) {
      return true;
    } else {
      return false;
    }
  }

  return true;
}

