def sync_tree(self):
    LOGGER.info("sync tree to host")

    # Create a sanitized copy of the tree with sensitive information removed
    import copy
    sanitized_tree = copy.deepcopy(self.tree_)

    # Remove weight information from all nodes
    def remove_sensitive_info(node):
        if hasattr(node, 'weight'):
            node.weight = None
        if hasattr(node, 'children') and node.children:
            for child in node.children:
                remove_sensitive_info(child)

    # Handle both tree list and single tree cases
    if isinstance(sanitized_tree, list):
        for tree in sanitized_tree:
            remove_sensitive_info(tree)
    else:
        remove_sensitive_info(sanitized_tree)

    self.transfer_inst.tree.remote(sanitized_tree,
                                   role=consts.HOST,
                                   idx=-1,
                                   encrypt=True)

