	req, err := c.newRequestWithURL(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}

	req.Header.Add("Range", fmt.Sprintf("bytes=%d-%d", start, end))

	// Create a copy of the HTTP client to modify redirect behavior
	clientCopy := *c.HTTPClient
	clientCopy.CheckRedirect = func(req *http.Request, via []*http.Request) error {
		// Remove Authorization header when redirecting to a different host
		if len(via) > 0 && via[0].URL.Host != req.URL.Host {
