func validateJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		 tok, err := jwt.ParseSigned(rawjwt)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		var claims struct {
			Expiry   *jwt.NumericDate `json:"exp,omitempty"`
			Audience []string         `json:"aud,omitempty"`
			Issuer   string           `json:"iss,omitempty"`
		}
		err = tok.Claims(key, &claims)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		// Check expiration claim
		if claims.Expiry == nil {
			return status.Error(codes.Unauthenticated, "JWT is missing expiration claim")
		}
		if time.Now().After(claims.Expiry.Time()) {
			return status.Error(codes.Unauthenticated, "JWT has expired")
		}

		// Validate audience claim
		expectedAudience := "databroker"
		audienceValid := false
		for _, aud := range claims.Audience {
			if aud == expectedAudience {
				audienceValid = true
				break
			}
		}
		if !audienceValid {
			return status.Errorf(codes.Unauthenticated, "JWT audience is invalid: expected %q", expectedAudience)
		}

		// Validate issuer claim
		expectedIssuer := "https://pomerium.example.com"
		if claims.Issuer != expectedIssuer {
			return status.Errorf(codes.Unauthenticated, "JWT issuer is invalid: expected %q, got %q", expectedIssuer, claims.Issuer)
		}
	}
	return nil
}

