def rebuild_auth(self, prepared_request, response):
    """When being redirected we may want to strip authentication from the
    request to avoid leaking credentials. This method intelligently removes
    and reapplies authentication where possible to avoid credential loss."""
    headers = prepared_request.headers
    url = prepared_request.url

    if 'Authorization' in headers:
        # If we should strip the auth, do it
        if self.should_strip_auth(response.request.url, url):
            del headers['Authorization']

    # .netrc might have more auth for us on our new host.
    new_auth = get_netrc_auth(url) if self.trust_env else None
    if new_auth is not None:
        prepared_request.prepare_auth(new_auth)

    return

def should_strip_auth(self, original_url, redirect_url):
    """Return True if we should strip the Authorization header when redirecting."""
    original_parsed = urlparse(original_url)
    redirect_parsed = urlparse(redirect_url)

    # Different hostnames require stripping
    if original_parsed.hostname != redirect_parsed.hostname:
        return True

    # Get effective ports with scheme defaults
    def get_effective_port(parsed):
        if parsed.port is not None:
            return parsed.port
        if parsed.scheme == 'http':
            return 80
        elif parsed.scheme == 'https':
            return 443
        return None

    original_port = get_effective_port(original_parsed)
    redirect_port = get_effective_port(redirect_parsed)

    # Same scheme but different ports require stripping
    if original_parsed.scheme == redirect_parsed.scheme:
        if original_port != redirect_port:
            return True

    # HTTPS to HTTP downgrade requires stripping
    if original_parsed.scheme == 'https' and redirect_parsed.scheme == 'http':
        return True

    # Otherwise, don't strip
    return False

