    if not locationHeaders:
        err = error.RedirectWithNoLocation(
            response.code, b"No location header field", uri
        )
        raise ResponseFailed([Failure(err)], response)
    location = self._resolveLocation(uri, locationHeaders[0])

    # Parse URIs to compare origins
    from urllib.parse import urlparse
    original_origin = urlparse(uri)
    redirect_origin = urlparse(location)

    # Check if redirect is cross-origin
    is_cross_origin = (original_origin.scheme, original_origin.netloc) != (
        redirect_origin.scheme, redirect_origin.netloc
    )

    # Create a copy of headers to modify, handling None case
    if headers is None:
        new_headers = Headers()
    else:
        new_headers = headers.copy()

    # Remove sensitive headers for cross-origin redirects
    if is_cross_origin:
        for header in list(new_headers.getAllRawHeaders()):
            if header[0].lower() in self._sensitiveHeaderNames:
                new_headers.removeHeader(header[0])

    deferred = self._agent.request(method, location, new_headers)

