func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)
		// Retrieve encrypted secret from database
		encryptedSecret, err := ds.Property(context.TODO()).Get(consts.JWTSecretKey)
		var secret string
		if err != nil || encryptedSecret == "" {
			log.Info("No encrypted JWT secret found. Generating and saving a new one")
			// Generate new secure secret
			secret = uuid.NewString()
			// Encrypt secret before storage (assumes secure encryption function exists)
			encrypted, err := EncryptString(secret)
			if err != nil {
				log.Fatal("Failed to encrypt JWT secret", err)
				return
			}
			// Save encrypted secret to database
			if err := ds.Property(context.TODO()).Set(consts.JWTSecretKey, encrypted); err != nil {
				log.Fatal("Failed to save encrypted JWT secret to database", err)
				return
			}
		} else {
			// Decrypt existing secret (assumes secure decryption function exists)
			var err error
			secret, err = DecryptString(encryptedSecret)
			if err != nil {
				log.Fatal("Failed to decrypt JWT secret", err)
				return
			}
		}
		Secret = []byte(secret)
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

