func New(opts ...Opts) (Manifest, error) {
	mc := manifestConfig{}
	for _, opt := range opts {
		opt(&mc)
	}
	c := common{
		r:         mc.r,
		desc:      mc.desc,
		rawBody:   mc.raw,
		rawHeader: mc.header,
	}
	// extract fields from header where available
	if mc.header != nil {
		if c.desc.MediaType == "" {
			c.desc.MediaType = mediatype.Base(mc.header.Get("Content-Type"))
		}
		if c.desc.Size == 0 {
			cl, _ := strconv.Atoi(mc.header.Get("Content-Length"))
			c.desc.Size = int64(cl)
		}
		// Verify header digest matches pinned digest if provided
		headerDigest, _ := digest.Parse(mc.header.Get("Docker-Content-Digest"))
		if c.desc.Digest != "" {
			if headerDigest != "" && c.desc.Digest != headerDigest {
				return nil, fmt.Errorf("manifest digest mismatch, expected %s, received %s", c.desc.Digest, headerDigest)
			}
		} else {
			c.desc.Digest = headerDigest
		}
		c.setRateLimit(mc.header)
	}
	if mc.orig != nil {
		return fromOrig(c, mc.orig)
	}
	return fromCommon(c)
}

