func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	// Use safe path resolution instead of unsafe methods
	resolved, err := fs.SafePath(p)
	if err != nil {
		return err
	}

	// Verify the resolved path is within the data directory
	if !fs.IsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any attempts to delete root server directory
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Check if path exists and is a symlink
	fileInfo, err := os.Lstat(resolved)
	if err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
	} else {
		// Check if path is a symlink
		if fileInfo.Mode()&os.ModeSymlink != 0 {
			// Resolve symlink target
			target, err := os.Readlink(resolved)
			if err != nil {
				return fmt.Errorf("failed to read symlink: %v", err)
			}
			// Get absolute path of the target
			targetAbs, err := filepath.Abs(filepath.Join(filepath.Dir(resolved), target))
			if err != nil {
				return fmt.Errorf("failed to resolve symlink target path: %v", err)
			}
			// Verify symlink target is within allowed directory
			if !fs.IsInDataDirectory(targetAbs) {
				return fmt.Errorf("cannot delete symlink pointing outside data directory: %s", target)
			}
		}

		if !fileInfo.IsDir() {
			fs.addDisk(-fileInfo.Size())
		} else {
			wg.Add(1)
			go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
				defer wg.Done()
				if s, err := fs.DirectorySize(resolved); err == nil {
					fs.addDisk(-s)
				}
			}(&wg, fileInfo, resolved)
		}
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

