func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	st, err := os.Lstat(resolved)
	if err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
	} else {
		// Check if path is a symlink pointing outside data directory
		if st.Mode()&os.ModeSymlink != 0 {
			target, err := os.Readlink(resolved)
			if err != nil {
				return errors.New("failed to read symlink: " + err.Error())
			}
			targetAbs, err := filepath.Abs(filepath.Join(filepath.Dir(resolved), target))
			if err != nil {
				return errors.New("failed to resolve symlink target path: " + err.Error())
			}
			if !fs.unsafeIsInDataDirectory(targetAbs) {
				return errors.New("cannot delete symlink pointing outside data directory: " + target)
			}
		}

		// Recursively check directory contents for symlinks pointing outside data directory
		if st.IsDir() {
			err := filepath.Walk(resolved, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				// Skip the root directory itself as we already checked it
				if path == resolved {
					return nil
				}
				if info.Mode()&os.ModeSymlink != 0 {
					target, err := os.Readlink(path)
					if err != nil {
						return errors.New("failed to read symlink " + path + ": " + err.Error())
					}
					targetAbs, err := filepath.Abs(filepath.Join(filepath.Dir(path), target))
					if err != nil {
						return errors.New("failed to resolve symlink target path: " + err.Error())
					}
					if !fs.unsafeIsInDataDirectory(targetAbs) {
						return errors.New("cannot delete directory containing symlink pointing outside data directory: " + target)
					}
				}
				return nil
			})
			if err != nil {
				return err
			}
		}

		// Original disk space calculation logic
		if !st.IsDir() {
			fs.addDisk(-st.Size())
		} else {
			wg.Add(1)
			go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
				defer wg.Done()
				if s, err := fs.DirectorySize(resolved); err == nil {
					fs.addDisk(-s)
				}
			}(&wg, st, resolved)
		}
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

